package net.dv8tion.runelite.petgrowthtracker.cat;

import net.runelite.api.Client;
import net.runelite.api.HashTable;
import net.runelite.api.WidgetNode;
import net.runelite.api.gameval.InterfaceID;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import javax.inject.Inject;

/**
 * The one piece of cat growth detection that genuinely needs {@code Client}:
 * whether a currently-open interface is one of the ones known to pause
 * kitten/cat growth. Pulled out on its own so it isn't buried in the middle
 * of {@link CatPetHandler} - the dog side's equivalent question ("is growth
 * currently allowed to progress?") lives just as visibly in
 * {@code DogTracker.tick()}, just answered by elapsed-since-fed time instead
 * of open interfaces, because that's the mechanic the game actually uses for
 * each species.
 *
 * This is only ever consulted as a fallback, when overhead text can't be
 * seen (a crowded area, or a teleport landing on the same tick as a growth
 * tick) - see {@link CatPetHandler#onGameTick()}.
 */
class CatGrowthGate
{
    /* InterfaceIDs for interfaces that stall kitten growth.  This is not all-inclusive.  It's just a makeshift
    replacement for watching for overhead text that would normally indicate kitten growth when the player count
    is very high and cant load all entities and your kitten might not be rendered.
    Rule of thumb: if you can't move around and keep the interface open, it will delay kitten growth if it is open.
     */
    private static final List<Integer> UNSAFE_IDS = new ArrayList<>(Arrays.asList(InterfaceID.JOURNALSCROLL,
            InterfaceID.GE_PRICECHECKER, InterfaceID.DEATHKEEP, InterfaceID.COLLECTION,
            InterfaceID.CHAT_RIGHT, InterfaceID.CHAT_LEFT, InterfaceID.CHATMENU,
            InterfaceID.OBJECTBOX_DOUBLE, InterfaceID.OBJECTBOX,
            InterfaceID.QUESTJOURNAL, InterfaceID.HOSIDIUS_SEEDBOX, InterfaceID.RUNE_POUCH,
            InterfaceID.TRAIL_CLUETEXT, InterfaceID.TRAIL_REWARDSCREEN,
            InterfaceID.TRAIL_MAP01, InterfaceID.TRAIL_MAP02, InterfaceID.TRAIL_MAP03,
            InterfaceID.TRAIL_MAP06, InterfaceID.TRAIL_MAP11,
            InterfaceID.EQUIPMENT,
            InterfaceID.CA_OVERVIEW, InterfaceID.CA_TASKS,
            InterfaceID.CA_BOSSES, InterfaceID.CA_REWARDS, InterfaceID.CRM_SURPRISEPOPUP_SIDE,
            InterfaceID.DISPLAYNAME, // believe it or not this does pause kitten growth
            InterfaceID.FAVOUR_KEYRING,
            InterfaceID.BOOKOFSCROLLS,
            InterfaceID.FORESTRY_KIT_MAIN, InterfaceID.FORESTRY_KIT_SIDE, // forestry main and side simultaneously open
            InterfaceID.GE_OFFERS, InterfaceID.BANK_DEPOSITBOX, InterfaceID.GE_COLLECT,
            InterfaceID.ITEMSETS, InterfaceID.ITEMSETS_SIDE, InterfaceID.GE_HISTORY,
            InterfaceID.SEED_VAULT, InterfaceID.QUESTSCROLL, InterfaceID.LEVELUP_DISPLAY,
            InterfaceID.FAIRYRINGS, InterfaceID.SHOPMAIN, InterfaceID.SLAYER_REWARDS,
            InterfaceID.CONFIRMDESTROY, InterfaceID.BANKPIN_KEYPAD, InterfaceID.BANKMAIN,
            InterfaceID.XPREWARD // same for book of knowledge from dunce random event
    ));

    private final Client client;

    @Inject
    CatGrowthGate(Client client)
    {
        this.client = client;
    }

    /** True if a known growth-pausing interface is currently open. */
    boolean isBlocked()
    {
        HashTable<WidgetNode> componentTable = client.getComponentTable();
        for (WidgetNode widgetNode : componentTable)
        {
            for (Integer unsafe : UNSAFE_IDS)
            {
                if (widgetNode.getId() == unsafe)
                {
                    return true;
                }
            }
        }
        return false;
    }
}

package net.dv8tion.runelite.petgrowthtracker;

import net.runelite.api.MenuAction;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.OverlayMenuEntry;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import org.apache.commons.lang3.time.DurationFormatUtils;

import javax.inject.Inject;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.font.TextAttribute;
import java.util.Collections;

/**
 * The panel that used to be {@code KittenOverlay}, generalised to paint
 * whichever {@link PetHandler} currently has something to say. Deliberately
 * kept as plain title + LineComponent rows - the look the kitten side
 * already had - rather than a custom-painted card, since the whole point of
 * this fork is to keep that UI for both species.
 */
public class PetOverlay extends OverlayPanel
{
    private final PetTrackerPlugin plugin;
    private final PetTrackerConfig config;

    @Inject
    private PetOverlay(PetTrackerPlugin plugin, PetTrackerConfig config)
    {
        super(plugin);
        setPosition(OverlayPosition.BOTTOM_LEFT);
        this.plugin = plugin;
        this.config = config;
        getMenuEntries().add(new OverlayMenuEntry(MenuAction.RUNELITE_OVERLAY_CONFIG, OverlayManager.OPTION_CONFIGURE, "Pet Tracker Overlay"));
        setPreferredSize(new Dimension(190, 88));
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        PetStatus status = plugin.activeStatus();
        if (status != null && !status.isEmpty())
        {
            panelComponent.getChildren().add(LineComponent.builder()
                    .leftFont(graphics.getFont().deriveFont(
                            Collections.singletonMap(
                                    TextAttribute.WEIGHT, TextAttribute.WEIGHT_BOLD)))
                    .left(status.getTitle())
                    .build());

            for (PetStatus.Row row : status.getRows())
            {
                panelComponent.getChildren().add(LineComponent.builder()
                        .left(row.getLabel() + ": ")
                        .rightColor(row.getValueColor())
                        .right(row.isDuration() ? formatDuration(row.getDurationMillis()) : row.getText())
                        .build());
            }
        }

        return super.render(graphics);
    }

    private String formatDuration(long millis)
    {
        return DurationFormatUtils.formatDuration(millis, config.displaySeconds() ? "H:mm:ss" : "H:mm", true);
    }
}

package net.dv8tion.runelite.petgrowthtracker;

/**
 * The common shape every species' NPC-id classification exposes: is this id
 * one of ours at all, and if so, has it finished growing?
 *
 * {@code net.dv8tion.runelite.petgrowthtracker.cat.FollowerKind} and {@code net.dv8tion.runelite.petgrowthtracker.dog.FollowerKind}
 * both implement this. Each is still its own enum with its own life stages -
 * a cat has three (kitten, cat, overgrown cat), a dog has two (puppy, dog) -
 * because that's genuinely how the two species differ in-game; this
 * interface only unifies the two questions {@link PetTrackerPlugin} actually
 * needs answered to route a follower: "is this mine?" and "is it done?".
 */
public interface PetLifeStage
{
    /** False for the "not this species" sentinel value (e.g. {@code NON_FELINE}, {@code NON_DOG}). */
    boolean isTracked();

    /** True for the final stage - the one where the pet no longer needs feeding/attention to keep growing. */
    boolean isFullyGrown();
}

package net.dv8tion.runelite.petgrowthtracker;

import com.google.inject.Provides;
import net.dv8tion.runelite.petgrowthtracker.cat.CatPetHandler;
import net.dv8tion.runelite.petgrowthtracker.dog.DogPetHandler;

import javax.inject.Inject;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.OverheadTextChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

/**
 * Tracks a cat/kitten or a puppy/dog follower, showing growth, hunger and
 * (for cats) attention countdowns in one overlay.
 *
 * This is a fork of the Kitten Tracker plugin, restructured around a
 * {@link PetHandler} per species so the same plugin can track either family
 * of pet: {@code CatPetHandler} carries over the original's growth-tick
 * engine unchanged, and {@code DogPetHandler} adds puppy/dog growth
 * tracking built around the account's own growth/feed varbits. This class's
 * job is just routing: work out which handler owns the current follower,
 * and forward every RuneLite event to it.
 *
 * Routing a follower is symmetric: both {@code CatPetHandler} and
 * {@code DogPetHandler} classify an NPC id via their own {@code FollowerKind}
 * enum (contiguous, known id ranges for every life stage of that species),
 * and whichever one claims the id owns every event for that follower. A
 * follower that neither recognises (a boss pet, a skilling pet) gets no
 * handler at all - {@link #species} stays {@code null} and the overlay shows
 * nothing, rather than guessing.
 */
@Slf4j
@PluginDescriptor(
        name = "Pet Growth Tracker",
        description = "Tracks the growth and hunger of your kitten/cat or puppy/dog, and warns you before it runs away or stops growing",
        tags = {"kitten", "cat", "puppy", "dog", "pet", "growth", "hunger", "status", "alert", "timer"}
)
public class PetTrackerPlugin extends Plugin
{
    private static final int VAR_PLAYER_FOLLOWER = 447;

    private static final String DIALOG_HAND_OVER_CAT_CIVILIAN = "You hand over the cat.You are given";
    private static final String DIALOG_GERTRUDE_GIVES_YOU_ANOTHER_KITTEN = "Gertrude gives you another kitten.";

    @Inject
    private Client client;
    @Inject
    private ClientThread clientThread;
    @Inject
    private OverlayManager overlayManager;
    @Inject
    private PetOverlay overlay;
    @Inject
    private CatPetHandler catHandler;
    @Inject
    private DogPetHandler dogHandler;

    private int followerID = 0;
    private PetSpecies species;

    @Provides
    PetTrackerConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(PetTrackerConfig.class);
    }

    @Override
    public void startUp()
    {
        overlayManager.add(overlay);
        // Deferred to the client thread, matching the original: startUp() isn't guaranteed
        // to already be running there, and Client state shouldn't be touched off it.
        clientThread.invokeLater(this::checkForFollower);
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
        catHandler.saveState();
        dogHandler.saveState();
    }

    private void checkForFollower()
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }

        if (playerHasFollower())
        {
            followerID = getCurrentFollowerId();
            if (followerID > 0)
            {
                classifyAndDispatch(followerID);
            }
        }
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event)
    {
        if (playerHasFollower() && followerID != getCurrentFollowerId())
        {
            followerID = getCurrentFollowerId();
            if (followerID > 0) // Varbit needs to fill up first after logging in
            {
                classifyAndDispatch(followerID);
            }
        }

        if (!playerHasFollower() && followerID != 0)
        {
            if (species != null)
            {
                activeHandler().onFollowerChanged(0);
            }
            followerID = 0;
            species = null;
        }
    }

    private void classifyAndDispatch(int npcId)
    {
        PetSpecies newSpecies;
        if (catHandler.isTrackedId(npcId))
        {
            newSpecies = PetSpecies.CAT;
        }
        else if (dogHandler.isTrackedId(npcId))
        {
            newSpecies = PetSpecies.DOG;
        }
        else
        {
            // Some other pet entirely (a boss pet, a skilling pet) - not ours to track.
            if (species != null)
            {
                activeHandler().onFollowerChanged(0);
            }
            species = null;
            return;
        }

        if (species != null && species != newSpecies)
        {
            activeHandler().onFollowerChanged(0);
        }

        species = newSpecies;
        activeHandler().onFollowerChanged(npcId);
    }

    private PetHandler activeHandler()
    {
        return species == PetSpecies.CAT ? catHandler : dogHandler;
    }

    /** Used by {@link PetOverlay}; {@code null} when there's nothing to paint. */
    PetStatus activeStatus()
    {
        return species == null ? null : activeHandler().status();
    }

    private int getCurrentFollowerId()
    {
        int followerVarPlayerValue = client.getVarpValue(VAR_PLAYER_FOLLOWER);
        // followerID is the first 2 bytes
        return (followerVarPlayerValue >> 16);
    }

    boolean playerHasFollower()
    {
        return (client.getVarpValue(VAR_PLAYER_FOLLOWER)) > 0;
    }

    @Subscribe
    public void onGameTick(GameTick tick)
    {
        if (species != null)
        {
            activeHandler().onGameTick();
        }

        Widget playerDialog = client.getWidget(InterfaceID.ChatRight.TEXT);
        if (playerDialog != null && species != null)
        {
            activeHandler().onDialogText(Text.removeTags(playerDialog.getText()));
        }

        Widget notificationDialog = client.getWidget(InterfaceID.Messagebox.TEXT);
        if (notificationDialog != null)
        {
            String notificationText = Text.removeTags(notificationDialog.getText());
            if (notificationText.equals(DIALOG_GERTRUDE_GIVES_YOU_ANOTHER_KITTEN))
            {
                // A brand new kitten - route to the cat handler regardless of what we were tracking before.
                species = PetSpecies.CAT;
            }
            if (species != null)
            {
                activeHandler().onDialogText(notificationText);
            }
        }

        Widget objectBoxDialog = client.getWidget(InterfaceID.OBJECTBOX, 2);
        if (objectBoxDialog != null && species != null)
        {
            String notificationText = Text.removeTags(objectBoxDialog.getText());
            if (notificationText.startsWith(DIALOG_HAND_OVER_CAT_CIVILIAN))
            {
                activeHandler().onDialogText(notificationText);
            }
        }
    }

    @Subscribe
    public void onOverheadTextChanged(OverheadTextChanged e)
    {
        if (species == PetSpecies.CAT && e.getActor().equals(client.getFollower()))
        {
            catHandler.onFollowerOverheadText();
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        if (event.getType() != ChatMessageType.GAMEMESSAGE)
        {
            return;
        }
        if (species == null)
        {
            return;
        }

        String message = Text.removeTags(event.getMessage());
        activeHandler().onChatMessage(message);
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        if (species != null)
        {
            activeHandler().onMenuOptionClicked(event);
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        catHandler.onGameStateChanged(event.getGameState());
        dogHandler.onGameStateChanged(event.getGameState());
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!event.getGroup().equals(PetTrackerConfig.GROUP))
        {
            return;
        }

        catHandler.onConfigChanged(event.getKey(), event.getNewValue());
        dogHandler.onConfigChanged(event.getKey(), event.getNewValue());
    }
}

