package net.dv8tion.runelite.petgrowthtracker;

import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * What a {@link PetHandler} wants shown in the overlay right now: a title
 * line plus a small number of label/value rows, each with its own colour.
 *
 * A row is either a countdown - given as raw milliseconds so {@link PetOverlay}
 * can apply the player's shared "display seconds" preference in one place -
 * or a literal piece of text ("Overgrown cat", "stopped growing"). Kept as a
 * plain, RuneLite-free DTO so both species build the same shape of output
 * and the overlay never needs to know which one produced it.
 */
public final class PetStatus
{
    public static final class Row
    {
        private final String label;
        private final Long durationMillis;
        private final String text;
        private final Color valueColor;

        private Row(String label, Long durationMillis, String text, Color valueColor)
        {
            this.label = label;
            this.durationMillis = durationMillis;
            this.text = text;
            this.valueColor = valueColor;
        }

        public String getLabel()
        {
            return label;
        }

        public boolean isDuration()
        {
            return durationMillis != null;
        }

        public long getDurationMillis()
        {
            return durationMillis == null ? 0L : durationMillis;
        }

        public String getText()
        {
            return text;
        }

        public Color getValueColor()
        {
            return valueColor;
        }
    }

    private final String title;
    private final List<Row> rows = new ArrayList<>();

    public PetStatus(String title)
    {
        this.title = title;
    }

    public PetStatus addDurationRow(String label, long durationMillis, Color valueColor)
    {
        rows.add(new Row(label, durationMillis, null, valueColor));
        return this;
    }

    public PetStatus addRow(String label, String text, Color valueColor)
    {
        rows.add(new Row(label, null, text, valueColor));
        return this;
    }

    public String getTitle()
    {
        return title;
    }

    public List<Row> getRows()
    {
        return Collections.unmodifiableList(rows);
    }

    public boolean isEmpty()
    {
        return rows.isEmpty();
    }
}

package net.dv8tion.runelite.petgrowthtracker;

import net.runelite.api.GameState;
import net.runelite.api.events.MenuOptionClicked;

/**
 * The state machine for one family of pet (cat or dog).
 *
 * {@link PetTrackerPlugin} owns the RuneLite subscriptions and decides which
 * single handler currently owns the player's follower; everything species
 * specific - what counts as growth, what the game's chat lines say, how a
 * feeding or a stroke changes the clocks - lives behind this interface so
 * the plugin and the overlay never need a species check of their own.
 */
public interface PetHandler
{
    /**
     * The tracked NPC id changed. {@code npcId == 0} means the player no
     * longer has a follower at all; any other value is a follower this
     * handler has been asked to own (the plugin has already decided this
     * handler is the right one, or - for dogs - that it's worth a provisional
     * look).
     */
    void onFollowerChanged(int npcId);

    /** Fires every game tick while this handler owns the current follower. */
    void onGameTick();

    /**
     * A game-message chat line arrived. Returns {@code true} if the line was
     * recognised as belonging to this species, purely so the plugin can log
     * when neither handler claims a line worth investigating.
     */
    boolean onChatMessage(String message);

    /**
     * Text read from a dialog/messagebox/objectbox widget this tick (guess
     * age replies, "has grown into a cat", turning a pet in, etc). Called
     * with {@code null} when no such widget is open.
     */
    void onDialogText(String text);

    void onMenuOptionClicked(MenuOptionClicked event);

    void onGameStateChanged(GameState state);

    /**
     * A plugin config value changed. {@code key} is the raw config key, e.g.
     * {@code "catAttentionOverlay"}.
     */
    void onConfigChanged(String key, String newValue);

    /** Whether this handler currently has anything worth showing or saving. */
    boolean isActive();

    /** {@code null} when there is nothing worth painting right now. */
    PetStatus status();

    /** Persist whatever clocks this handler is keeping, e.g. on shutdown. */
    void saveState();
}

package net.dv8tion.runelite.petgrowthtracker.dog;

import net.dv8tion.runelite.petgrowthtracker.PetLifeStage;
import net.runelite.api.gameval.NpcID;

/**
 * Which canine life-stage a follower NPC id belongs to, or {@link #NON_DOG}
 * if it isn't one of ours - the same shape as
 * {@code net.dv8tion.runelite.petgrowthtracker.cat.FollowerKind}, using the two contiguous id
 * blocks Jagex actually ships: {@code LABRADOR_YELLOW}..{@code YORKIE_YELLOW}
 * for the twelve breeds' adult form, and {@code LABRADOR_YELLOW_PUPPY}..
 * {@code YORKIE_YELLOW_PUPPY} for the same twelve breeds' puppy form (three
 * colours each). The "wander"/"shelter" ids in between are wild, pre-adoption
 * dogs, never a player's follower, so they don't need excluding - they simply
 * aren't a follower id the plugin will ever see here.
 *
 * These constants only exist in {@code net.runelite.api.gameval.NpcID}
 * (puppies are 2026-09-08 content); the legacy {@code net.runelite.api.NpcID}
 * has the same numeric ranges under uglier per-id names
 * ({@code LABRADOR_PUPPY}, {@code LABRADOR_PUPPY_16434}, ...), which is why
 * this class uses gameval while the cat side still uses the legacy class.
 */
public enum FollowerKind implements PetLifeStage {
    PUPPY, DOG, NON_DOG;

    public static FollowerKind getFromFollowerId(int followerId) {
        if (followerId >= NpcID.LABRADOR_YELLOW && followerId <= NpcID.YORKIE_YELLOW) {
            return DOG;
        } else if (followerId >= NpcID.LABRADOR_YELLOW_PUPPY && followerId <= NpcID.YORKIE_YELLOW_PUPPY) {
            return PUPPY;
        } else {
            return NON_DOG;
        }
    }

    @Override
    public boolean isTracked() {
        return this != NON_DOG;
    }

    @Override
    public boolean isFullyGrown() {
        return this == DOG;
    }
}

package net.dv8tion.runelite.petgrowthtracker.dog;

import net.dv8tion.runelite.petgrowthtracker.PetHandler;
import net.dv8tion.runelite.petgrowthtracker.PetStatus;
import net.dv8tion.runelite.petgrowthtracker.PetTrackerConfig;

import java.awt.Color;

import javax.inject.Inject;
import javax.inject.Singleton;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.Notifier;

/**
 * The puppy/dog RuneLite adapter: polls the two server-side growth varbits
 * (see {@link DogTracker}) and turns their edges into notifications and an
 * overlay status.
 *
 * There is deliberately no persistence here, unlike the cat side. A cat's
 * growth has to be reconstructed client-side across a relog because nothing
 * server-side exposes it; a puppy's growth is a live account value the
 * server already remembers, so re-reading the varbit after logging back in
 * gives the exact answer with no client-side bookkeeping at all. Likewise
 * there's no menu-click feed detection or chat parsing: the fed-timer varbit
 * only resets on a feed the server actually accepted, so there's nothing to
 * infer and nothing a refused feed could get wrong.
 */
@Slf4j
@Singleton
public class DogPetHandler implements PetHandler
{
    private final Client client;
    private final Notifier notifier;
    private final PetTrackerConfig config;

    private final DogTracker tracker = new DogTracker();

    private FollowerKind followerKind = FollowerKind.NON_DOG;

    private boolean warnedHungry;
    private boolean warnedVeryHungry;
    private boolean warnedPaused;
    private boolean warnedGrown;

    @Inject
    public DogPetHandler(Client client, Notifier notifier, PetTrackerConfig config)
    {
        this.client = client;
        this.notifier = notifier;
        this.config = config;
    }

    public boolean isTrackedId(int npcId)
    {
        return FollowerKind.getFromFollowerId(npcId).isTracked();
    }

    @Override
    public void onFollowerChanged(int npcId)
    {
        followerKind = FollowerKind.getFromFollowerId(npcId);
        warnedHungry = false;
        warnedVeryHungry = false;
        warnedPaused = false;
        warnedGrown = false;

        if (followerKind == FollowerKind.DOG)
        {
            // The id alone tells us this one has already finished growing - no need to read a varbit for it.
            tracker.grownUp();
        }
    }

    @Override
    public void onGameTick()
    {
        NPC follower = client.getFollower();
        tracker.setFollowing(follower != null, follower == null ? null : follower.getName());

        if (followerKind == FollowerKind.PUPPY)
        {
            int growthMinutes = client.getVarbitValue(VarbitID.PUPPY_GROWTH_TRACKER);
            int fedMinutes = client.getVarbitValue(VarbitID.PUPPY_FED_TIMER);
            tracker.update(growthMinutes, fedMinutes);
        }

        checkNotifications();
    }

    @Override
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        // Feeding is read back from the fed-timer varbit, not the menu click that caused it.
    }

    @Override
    public boolean onChatMessage(String message)
    {
        // Growth and feed state come straight from varbits; no chat line carries anything the varbits don't already say.
        return false;
    }

    @Override
    public void onDialogText(String text)
    {
        // Nothing to parse - see onChatMessage.
    }

    @Override
    public void onGameStateChanged(GameState state)
    {
        if (state != GameState.LOGGED_IN)
        {
            tracker.setFollowing(false, null);
        }
    }

    @Override
    public void onConfigChanged(String key, String newValue)
    {
        // Nothing to re-arm live; the next tick/status() call reads the config directly.
    }

    @Override
    public boolean isActive()
    {
        return followerKind.isTracked();
    }

    @Override
    public void saveState()
    {
        // Nothing to save - see the class-level note on why this class has no persistence.
    }

    private void checkNotifications()
    {
        if (!tracker.isFollowing())
        {
            return;
        }

        if (tracker.isFullyGrown())
        {
            if (!warnedGrown)
            {
                warnedGrown = true;
                if (config.dogNotifications())
                {
                    notifier.notify("Your puppy has grown into a dog");
                }
            }
            return;
        }

        if (!tracker.isHungry())
        {
            // Freshly fed (or never let it get hungry) - re-arm every warning for the next cycle.
            warnedHungry = false;
            warnedVeryHungry = false;
            warnedPaused = false;
            return;
        }

        if (tracker.isGrowthPaused())
        {
            if (!warnedPaused)
            {
                warnedPaused = true;
                if (config.dogNotifications())
                {
                    notifier.notify("Your puppy has stopped growing. You'll need to feed it for it to continue doing so.");
                }
            }
        }
        else if (tracker.isVeryHungry())
        {
            if (!warnedVeryHungry)
            {
                warnedVeryHungry = true;
                if (config.dogNotifications())
                {
                    notifier.notify("Your puppy is very hungry.");
                }
            }
        }
        else if (!warnedHungry)
        {
            warnedHungry = true;
            if (config.dogNotifications())
            {
                notifier.notify("Your puppy is getting quite hungry.");
            }
        }
    }

    @Override
    public PetStatus status()
    {
        if (!followerKind.isTracked() || !tracker.isFollowing())
        {
            return null;
        }

        if (tracker.isFullyGrown())
        {
            if (config.dogHideWhenGrown() || !config.dogOverlay())
            {
                return null;
            }
            return new PetStatus("Dog status").addRow("Status", tracker.petName() + " (grown)", Color.WHITE);
        }

        PetStatus status = new PetStatus("Puppy status");
        boolean paused = tracker.isGrowthPaused();

        if (config.dogOverlay())
        {
            status.addDurationRow("Grown up in", tracker.untilGrownMillis(), paused ? Color.RED : Color.WHITE);
        }

        if (config.dogFeedOverlay())
        {
            if (paused)
            {
                status.addRow("Hungry in", "stopped growing", Color.RED);
            }
            else
            {
                Color color = tracker.isVeryHungry() ? Color.RED : tracker.isHungry() ? Color.ORANGE : Color.WHITE;
                status.addDurationRow("Hungry in", tracker.untilPausedMillis(), color);
            }
        }

        return status.isEmpty() ? null : status;
    }
}

package net.dv8tion.runelite.petgrowthtracker.dog;

/**
 * A puppy's growth, read straight from the server rather than inferred.
 *
 * The account carries two varbits for the currently-followed puppy -
 * {@code VarbitID.PUPPY_GROWTH_TRACKER} (active-growth minutes so far) and
 * {@code VarbitID.PUPPY_FED_TIMER} (minutes since last fed) - confirmed
 * directly against the real client jar: both increment together while
 * growing, the growth tracker alone halts once the puppy needs feeding, and
 * feeding resets the fed timer to zero.
 *
 * An earlier version of this class instead banked growth in milliseconds and
 * inferred pauses from feed timestamps, the kind of workaround the cat side
 * still needs because no equivalent varbit exists for kittens. With the
 * server doing the accounting, there is nothing left to reconstruct: no
 * banked-growth clock to accrue, no "Guess age" dialog to parse, no
 * menu-click feed detection or refusal-window rollback (the fed timer is a
 * server value that only a real, successful feed resets), and no needing to
 * know a growth-blocking interface list at all - see
 * {@link DogPetHandler#onGameTick()}, which simply polls both varbits every
 * tick.
 *
 * Pause detection reads {@code fedMinutes} directly against a fixed cutoff,
 * rather than watching the growth tracker for a stall (an even earlier
 * version of this class did that instead). That was more "self-calibrating"
 * in theory, but it made the whole thing exactly as laggy as the growth
 * tracker's own once-a-minute cadence in <em>both</em> directions: slow to
 * notice a pause, and - what testing actually surfaced - just as slow to
 * notice a feed had ended one, since resuming still had to wait for the
 * counter to visibly tick over again. {@code fedMinutes} itself updates the
 * instant the server registers a feed, so reading it directly is both
 * simpler and immediately responsive.
 *
 * The three minute thresholds below are the OSRS Wiki's, read verbatim from
 * <a href="https://oldschool.runescape.wiki/w/Puppy#Hunger">the Puppy
 * page's Hunger section</a>: "Your puppy is getting quite hungry" at 15
 * minutes, "Your puppy is very hungry" at 25, and "Your puppy has stopped
 * growing..." at 30.
 *
 * Holds no RuneLite types, so it's exercised with plain numbers rather than
 * a live client.
 */
class DogTracker
{
    /** Active growth needed to become a dog: three hours, i.e. 180 minutes on the growth-tracker varbit. */
    static final int GROWTH_MINUTES = 180;

    /** Minutes unfed before "Your puppy is getting quite hungry." */
    static final int HUNGRY_WARNING_MINUTES = 15;

    /** Minutes unfed before "Your puppy is very hungry." */
    static final int VERY_HUNGRY_WARNING_MINUTES = 25;

    /** Minutes unfed before "Your puppy has stopped growing..." - growth pauses until the next feed. */
    static final int FEED_PAUSE_MINUTES = 30;

    private int growthMinutes;
    private int fedMinutes;
    private boolean fullyGrown;
    private boolean following;
    private String petName;

    /** Called every tick a puppy follower is present, with the two varbits read fresh. */
    void update(int growthMinutes, int fedMinutes)
    {
        this.growthMinutes = growthMinutes;
        this.fedMinutes = fedMinutes;

        if (growthMinutes >= GROWTH_MINUTES)
        {
            fullyGrown = true;
        }
    }

    void setFollowing(boolean following, String petName)
    {
        this.following = following;
        if (petName != null && !petName.isEmpty())
        {
            this.petName = petName;
        }
    }

    /** The NPC id itself says this one already finished growing - no varbit needed to know that. */
    void grownUp()
    {
        fullyGrown = true;
        growthMinutes = GROWTH_MINUTES;
    }

    boolean isFollowing()
    {
        return following;
    }

    boolean isFullyGrown()
    {
        return fullyGrown;
    }

    String petName()
    {
        return petName == null ? "Puppy" : petName;
    }

    int fedMinutes()
    {
        return fedMinutes;
    }

    /** True once unfed for {@link #FEED_PAUSE_MINUTES} - growth has stopped until the next feed. */
    boolean isGrowthPaused()
    {
        return !fullyGrown && fedMinutes >= FEED_PAUSE_MINUTES;
    }

    /** True from {@link #HUNGRY_WARNING_MINUTES} - "Your puppy is getting quite hungry." */
    boolean isHungry()
    {
        return !fullyGrown && fedMinutes >= HUNGRY_WARNING_MINUTES;
    }

    /** True from {@link #VERY_HUNGRY_WARNING_MINUTES} - "Your puppy is very hungry." */
    boolean isVeryHungry()
    {
        return !fullyGrown && fedMinutes >= VERY_HUNGRY_WARNING_MINUTES;
    }

    /** Remaining active growth in milliseconds; 0 once fully grown. */
    long untilGrownMillis()
    {
        return Math.max(0L, (long) (GROWTH_MINUTES - growthMinutes) * 60_000L);
    }

    /** Milliseconds until growth pauses from hunger; 0 once it already has. */
    long untilPausedMillis()
    {
        return Math.max(0L, (long) (FEED_PAUSE_MINUTES - fedMinutes) * 60_000L);
    }
}
